import os
import queue
import threading
from typing import Iterator, Optional

import pyaudio
import azure.cognitiveservices.speech as speechsdk


class MicrophoneTranscriptStreamer:
    def __init__(
        self,
        language: str = "en-US",
        sample_rate: int = 16000,
        chunk_size: int = 1024,
        device_name: Optional[str] = None,
    ):
        self.language = language
        self.sample_rate = sample_rate
        self.chunk_size = chunk_size
        self.device_name = device_name

        self._audio_queue: "queue.Queue[Optional[bytes]]" = queue.Queue()
        self._stop_event = threading.Event()
        self._recognizer = None
        self._audio_stream = None
        self._pyaudio = None
        self._speech_config = None
        self._audio_config = None

    def _build_recognizer(self):
        speech_key = os.environ.get("AZURE_SPEECH_KEY")
        speech_region = os.environ.get("AZURE_SPEECH_REGION")
        if not speech_key or not speech_region:
            raise RuntimeError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION must be set")

        self._speech_config = speechsdk.SpeechConfig(
            subscription=speech_key, region=speech_region
        )
        self._speech_config.speech_recognition_language = self.language

        self._pyaudio = pyaudio.PyAudio()

        device_index = None
        if self.device_name is not None:
            for i in range(self._pyaudio.get_device_count()):
                info = self._pyaudio.get_device_info_by_index(i)
                if self.device_name.lower() in info.get("name", "").lower():
                    device_index = i
                    break
            if device_index is None:
                raise RuntimeError(f'Microphone device containing "{self.device_name}" not found')

        self._audio_stream = self._pyaudio.open(
            format=pyaudio.paInt16,
            channels=1,
            rate=self.sample_rate,
            input=True,
            input_device_index=device_index,
            frames_per_buffer=self.chunk_size,
            stream_callback=self._pyaudio_callback,
        )

        push_stream = speechsdk.audio.PushAudioInputStream()
        self._audio_config = speechsdk.audio.AudioConfig(stream=push_stream)
        self._recognizer = speechsdk.SpeechRecognizer(
            speech_config=self._speech_config, audio_config=self._audio_config
        )
        return push_stream

    def _pyaudio_callback(self, in_data, frame_count, time_info, status):
        if not self._stop_event.is_set():
            self._audio_queue.put(in_data)
        return (None, pyaudio.paContinue)

    def transcripts(self) -> Iterator[str]:
        push_stream = self._build_recognizer()

        def feeder():
            try:
                while not self._stop_event.is_set():
                    chunk = self._audio_queue.get()
                    if chunk is None:
                        break
                    push_stream.write(chunk)
            finally:
                try:
                    push_stream.close()
                except Exception:
                    pass

        feeder_thread = threading.Thread(target=feeder, daemon=True)
        feeder_thread.start()

        interim_queue: "queue.Queue[str]" = queue.Queue()

        def recognized_cb(evt):
            text = getattr(evt.result, "text", "") or ""
            if text:
                interim_queue.put(text)

        def canceled_cb(evt):
            self._stop_event.set()

        self._recognizer.recognized.connect(recognized_cb)
        self._recognizer.canceled.connect(canceled_cb)

        self._recognizer.start_continuous_recognition()

        try:
            if self._audio_stream is not None:
                self._audio_stream.start_stream()

            while not self._stop_event.is_set():
                try:
                    yield interim_queue.get(timeout=0.1)
                except queue.Empty:
                    continue
        finally:
            self._stop_event.set()
            try:
                if self._recognizer is not None:
                    self._recognizer.stop_continuous_recognition()
            except Exception:
                pass
            try:
                self._audio_queue.put(None)
            except Exception:
                pass
            try:
                if self._audio_stream is not None:
                    self._audio_stream.stop_stream()
                    self._audio_stream.close()
            except Exception:
                pass
            try:
                if self._pyaudio is not None:
                    self._pyaudio.terminate()
            except Exception:
                pass
            feeder_thread.join(timeout=2.0)


def stream_microphone_transcripts(
    language: str = "en-US",
    sample_rate: int = 16000,
    chunk_size: int = 1024,
    device_name: Optional[str] = None,
) -> Iterator[str]:
    streamer = MicrophoneTranscriptStreamer(
        language=language,
        sample_rate=sample_rate,
        chunk_size=chunk_size,
        device_name=device_name,
    )
    yield from streamer.transcripts()
